begin;
select plan(19);
insert into auth.users(id) values ('58000000-0000-4000-8000-000000000001');
insert into auth.sessions(id,user_id) values ('68000000-0000-4000-8000-000000000001','58000000-0000-4000-8000-000000000001');
insert into public.staff_members(user_id,active,display_name) values ('58000000-0000-4000-8000-000000000001',true,'Equipe de teste');
insert into public.animals(id,name,species,sex,size,approximate_age) values ('78000000-0000-4000-8000-000000000001','Fixture programação','dog','female','small','2');
create temporary table schedule_test(kind text,value jsonb);grant all on schedule_test to authenticated;
select set_config('request.jwt.claims','{"sub":"58000000-0000-4000-8000-000000000001","session_id":"68000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
insert into schedule_test select 'fixed',public.save_medication_treatment(repeat('a',32),'{"animal_id":"78000000-0000-4000-8000-000000000001","medication_name":" Exemplo ","schedule_mode":"fixed_times","starts_on":"2026-11-01","starts_time":"08:00","ends_on":"2026-11-02","ends_time":"20:00","fixed_times":["20:00","08:00"]}');
select is((select value->'result'->'treatment'->>'medication_name' from schedule_test where kind='fixed'),'Exemplo','name normalized');
select is((select count(*)::int from public.medication_applications where treatment_id=(select (value->'result'->'treatment'->>'id')::uuid from schedule_test where kind='fixed')),4,'fixed schedule includes both boundaries');
select is(public.save_medication_treatment(repeat('a',32),'{"animal_id":"78000000-0000-4000-8000-000000000001","medication_name":"Exemplo","schedule_mode":"fixed_times","starts_on":"2026-11-01","starts_time":"08:00","ends_on":"2026-11-02","ends_time":"20:00","fixed_times":["08:00","20:00"]}'),(select value from schedule_test where kind='fixed'),'normalized replay keeps same confirmation');
select throws_ok($$select public.save_medication_treatment(repeat('a',32),'{"animal_id":"78000000-0000-4000-8000-000000000001","medication_name":"Outro","schedule_mode":"fixed_times","starts_on":"2026-11-01","starts_time":"08:00","ends_on":"2026-11-02","ends_time":"20:00","fixed_times":["08:00","20:00"]}')$$,'PT409','operation_conflict','key changed payload conflicts');
insert into schedule_test select 'interval',public.save_medication_treatment(repeat('b',32),'{"animal_id":"78000000-0000-4000-8000-000000000001","medication_name":"Intervalo","schedule_mode":"interval","starts_on":"2026-11-01","starts_time":"20:00","ends_on":"2026-11-02","ends_time":"20:00","fixed_times":[],"interval_minutes":480}');
select is((select count(*)::int from public.medication_applications where treatment_id=(select (value->'result'->'treatment'->>'id')::uuid from schedule_test where kind='interval')),4,'elapsed interval crosses midnight with inclusive end');
select is((select to_char(min(scheduled_at) at time zone 'America/Sao_Paulo','HH24:MI') from public.medication_applications where treatment_id=(select (value->'result'->'treatment'->>'id')::uuid from schedule_test where kind='interval') and (scheduled_at at time zone 'America/Sao_Paulo')::date='2026-11-02'),'04:00','next day retains eight elapsed hours');
select throws_ok($$select public.save_medication_treatment(repeat('c',32),'{"animal_id":"78000000-0000-4000-8000-000000000001","medication_name":"Gap","schedule_mode":"fixed_times","starts_on":"2018-11-04","starts_time":"00:30","ends_on":"2018-11-05","ends_time":"20:00","fixed_times":["00:30"]}')$$,'22023','invalid_payload','nonexistent civil time rejected');
select throws_ok($$select public.save_medication_treatment(repeat('d',32),'{"animal_id":"78000000-0000-4000-8000-000000000001","medication_name":"Fold","schedule_mode":"fixed_times","starts_on":"2019-02-16","starts_time":"23:30","ends_on":"2019-02-17","ends_time":"20:00","fixed_times":["23:30"]}')$$,'22023','invalid_payload','ambiguous civil time rejected');
select throws_ok($$select public.save_medication_treatment(repeat('e',32),'{"animal_id":"78000000-0000-4000-8000-000000000001","medication_name":"Inválido","schedule_mode":"fixed_times","starts_on":"2026-02-31","starts_time":"08:00","ends_on":"2026-11-02","ends_time":"20:00","fixed_times":["08:00"]}')$$,'22023','invalid_payload','invalid calendar rejected');
select throws_ok($$select public.save_medication_treatment(repeat('f',32),'{"animal_id":"78000000-0000-4000-8000-000000000001","medication_name":"Duplicado","schedule_mode":"fixed_times","starts_on":"2026-11-01","starts_time":"08:00","ends_on":"2026-11-02","ends_time":"20:00","fixed_times":["08:00","08:00"]}')$$,'22023','invalid_payload','duplicate fixed slots rejected');
select throws_ok($$select public.save_medication_treatment(repeat('u',32),'{"animal_id":"78000000-0000-4000-8000-000000000001","medication_name":"Injeção","schedule_mode":"interval","starts_on":"2026-11-01","starts_time":"08:00","ends_on":"2026-11-02","ends_time":"20:00","fixed_times":[],"interval_minutes":480,"performed_by":"58000000-0000-4000-8000-000000000001"}')$$,'22023','invalid_payload','unknown actor field rejected');
select throws_ok($$select public.save_medication_treatment(repeat('v',32),'{"animal_id":"78000000-0000-4000-8000-000000000001","medication_name":"Longo","schedule_mode":"interval","starts_on":"2026-01-01","starts_time":"08:00","ends_on":"2027-01-02","ends_time":"20:00","fixed_times":[],"interval_minutes":480}')$$,'22023','invalid_payload','period beyond inclusive 366 days rejected');
select throws_ok($$select public.save_medication_treatment(repeat('w',32),'{"animal_id":"78000000-0000-4000-8000-000000000001","medication_name":"Intervalo zero","schedule_mode":"interval","starts_on":"2026-11-01","starts_time":"08:00","ends_on":"2026-11-02","ends_time":"20:00","fixed_times":[],"interval_minutes":0}')$$,'22023','invalid_payload','zero interval rejected');
insert into schedule_test select 'limit',public.save_medication_treatment(repeat('g',32),'{"animal_id":"78000000-0000-4000-8000-000000000001","medication_name":"Limite","schedule_mode":"interval","starts_on":"2026-11-01","starts_time":"08:00","ends_on":"2026-11-08","ends_time":"06:39","fixed_times":[],"interval_minutes":1}');
select is((select count(*)::int from public.medication_applications where treatment_id=(select (value->'result'->'treatment'->>'id')::uuid from schedule_test where kind='limit')),10000,'10000 applications supported without truncation');
select throws_ok($$select public.save_medication_treatment(repeat('h',32),'{"animal_id":"78000000-0000-4000-8000-000000000001","medication_name":"Excesso","schedule_mode":"interval","starts_on":"2026-11-01","starts_time":"08:00","ends_on":"2026-11-08","ends_time":"06:40","fixed_times":[],"interval_minutes":1}')$$,'22023','invalid_payload','10001 applications rejected atomically');
select is((select count(*)::int from public.medication_treatments t join public.medication_treatment_revisions r on r.treatment_id=t.id and r.revision=t.current_revision where r.medication_name='Excesso'),0,'excess leaves no treatment');
select is((public.get_medication_operation(repeat('a',32))),(select value from schedule_test where kind='fixed'),'actor can reconcile same receipt');
select is(jsonb_array_length(public.list_animal_medication_treatments('78000000-0000-4000-8000-000000000001',null)->'items'),3,'treatments list includes confirmed records');
reset role;
update public.staff_members set active=false where user_id='58000000-0000-4000-8000-000000000001';
set local role authenticated;
select throws_ok($$select public.get_medication_operation(repeat('a',32))$$,'42501','staff_required','revoked staff cannot reconcile private receipt');
select * from finish();rollback;
